import { chromium } from 'playwright';
const base=process.env.KP_AUDIT_URL||'http://127.0.0.1:4173/';
const old='2026-08-12T12:00:00+02:00',fresh='2026-08-14T00:01:00+02:00';
const pic='data:image/svg+xml;base64,'+Buffer.from('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><rect width="100" height="100" fill="#789"/></svg>').toString('base64');
const initial={visited:['bernatek'],missionStatus:{bernatek:{done:true,updatedAt:old}},missionEvidence:{bernatek:{id:'bernatek',verified:true,photo:pic,title:'OLD',comment:'old',by:'Ismael',completedAt:old,updatedAt:old}},memories:[],expenses:[],config:{dailyTarget:21,fixedPaid:0},updatedAt:old};
const browser=await chromium.launch({headless:true}),context=await browser.newContext({serviceWorkers:'block'});await context.addInitScript(s=>localStorage.setItem('krakowPocketCoop',JSON.stringify(s)),initial);
let server=structuredClone(initial),phase='boot';const network=[];
await context.route('https://ahzmwkztlakejmrvgcdm.supabase.co/rest/v1/rpc/**',async r=>{const u=r.request().url(),at=Date.now();if(u.includes('adventure_get')){network.push({at,phase,type:'GET',server:server.missionEvidence?.bernatek?.title,updatedAt:server.missionEvidence?.bernatek?.updatedAt,memories:server.memories?.length});return r.fulfill({status:200,contentType:'application/json',body:JSON.stringify(server)})}if(u.includes('adventure_put')){let incoming={};try{incoming=JSON.parse(r.request().postData()||'{}').p_state||{}}catch{};network.push({at,phase,type:'PUT',incoming:incoming.missionEvidence?.bernatek?.title,updatedAt:incoming.missionEvidence?.bernatek?.updatedAt,before:server.missionEvidence?.bernatek?.title,memories:incoming.memories?.length});server=structuredClone(incoming);return r.fulfill({status:200,contentType:'application/json',body:'{}'})}return r.fulfill({status:200,body:'{}'})});
const page=await context.newPage();await page.goto(base,{waitUntil:'domcontentloaded'});await page.waitForFunction(()=>window.KP_STATE_BRIDGE?.version==='1.7');await page.waitForTimeout(1800);
phase='local-edits';await page.evaluate(()=>document.querySelector('.tab[data-panel="diary"]')?.click());for(const [title,note] of [['ONE','first'],['TWO','second'],['THREE','third']]){await page.evaluate(([title,note])=>{memoryTitle.value=title;memoryNote.value=note;memoryPlace.value='Cracovia';memoryForm.requestSubmit()},[title,note]);await page.waitForTimeout(900)}await page.waitForTimeout(1800);
phase='baseline';server=structuredClone(JSON.parse(await page.evaluate(()=>localStorage.getItem('krakowPocketCoop'))));network.push({at:Date.now(),phase,type:'BASELINE',server:server.missionEvidence?.bernatek?.title,memories:server.memories?.length});
phase='inject';server.missionEvidence.bernatek={...server.missionEvidence.bernatek,title:'REMOTE',comment:'remote',by:'Laura',updatedAt:fresh};server.updatedAt=fresh;network.push({at:Date.now(),phase,type:'INJECT',server:'REMOTE'});
phase='reconnect';await page.evaluate(()=>document.getElementById('reconnectCloud')?.click());
const samples=[];for(let i=0;i<28;i++){await page.waitForTimeout(500);samples.push(await page.evaluate(i=>{let s={};try{s=JSON.parse(localStorage.getItem('krakowPocketCoop')||'{}')}catch{};const p=window.KP_STATE_BRIDGE?.protectedMissionEvidence?.()||{};return{i,local:s.missionEvidence?.bernatek?.title,localTs:s.missionEvidence?.bernatek?.updatedAt,protected:p.bernatek?.title,protectedTs:p.bernatek?.updatedAt,memories:s.memories?.length,syncText:document.getElementById('syncText')?.textContent}},i))}
console.log(JSON.stringify({server:{title:server.missionEvidence?.bernatek?.title,ts:server.missionEvidence?.bernatek?.updatedAt,memories:server.memories?.length},samples,network},null,2));if(samples.some(x=>x.local!=='REMOTE'||x.protected!=='REMOTE')||server.missionEvidence?.bernatek?.title!=='REMOTE')process.exitCode=1;await browser.close();